       {
        "h": "1.4: Length",
        "blocks": [
         {
          "t": "p",
          "x": ": LENGTH The length of an object is a measurement of its longest dimension. e.g. we think of the length of the edge of a table"
         },
         {
          "t": "ul",
          "items": [
           "The length of an edge of a table",
           "We can also estimate how long something is and find out by measuring it. in meters (m) or centimeters (cm). Longer units such",
           "We can also estimate how long something is and find out by measuring",
           "Length is measured in meters (m) or centimeters (cm). Longer units such as kilometers (1000m)"
          ]
         },
         {
          "t": "p",
          "x": "or mega meters (1,000,000m) are also used."
         }
        ]
       },
       {
        "h": "Conversion of units of length (distance)",
        "blocks": [
         {
          "t": "p",
          "x": "1cm=10mm,1m=100cm,1km=1000m,1mg=1,000,000m"
         }
        ]
       },
       {
        "h": "1.5: Volume",
        "blocks": [
         {
          "t": "ul",
          "items": [
           "Volume means 'space occupied 'by a 3-dimensional object."
          ]
         },
         {
          "t": "formula",
          "x": "- The S.I. unit of volume is cubic meters (m^3) or cubic centimeters (cm^3) or cubic decimeters"
         },
         {
          "t": "ul",
          "items": [
           "The volume of liquid is usually measured in litters(l) and milliliters(ml)"
          ]
         }
        ]
       },
       {
        "h": "Conversion of units of volume",
        "blocks": [
         {
          "t": "formula",
          "x": "1 litre = 1000 mililiters, 1 m^3 = 1000 litres,\n1 m^3 = 100000 ml = 1000000 cm^3"
         },
         {
          "t": "ol",
          "items": [
           "5.1. To measure the volume of regular solid objects."
          ]
         },
         {
          "t": "p",
          "x": "Cubes of sugar, cement blocks, bars of soap, box of matches are all examples of regular solid objects."
         },
         {
          "t": "p",
          "x": "We can find the volume of regular solid objects by measuring the length, breadth and the height and multiplying all three values."
         },
         {
          "t": "p",
          "x": "Volume = length x breadth x height"
         },
         {
          "t": "p",
          "x": "Example 1: Find the volume of a cuboid 18 cm long, 10 cm wide and 12 cm high"
         },
         {
          "t": "p",
          "x": "Solution: Volume = Length x breadth x height"
         },
         {
          "t": "formula",
          "x": "= 18 x 10 x 12\n= 2160 cm^3"
         },
         {
          "t": "img",
          "src": "images/foundation-science/3-3-1-volume-of-cuboid.png",
          "alt": "Figure: 3.3.1. Volume of cuboid"
         },
         {
          "t": "p",
          "x": "Figure: 3.3.1. Volume of cuboid"
         },
         {
          "t": "ol",
          "items": [
           "5.2: How to measure volume of a cylindrical object e.g. water tank, drums or reservoir Measure the height and diameter of the cylindrical object."
          ]
         },
         {
          "t": "p",
          "x": "Use the formula shown below to calculate the volume."
         },
         {
          "t": "formula",
          "x": "Volumeofacylinder = r^2h , where"
         },
         {
          "t": "formula",
          "x": "pi = 2 2 / 7 (or 3.14), r = radius (which is half of the diameter), h = height of the cylinder"
         }
        ]
       },
       {
        "h": "Worked example",
        "blocks": [
         {
          "t": "p",
          "x": "Calculate the volume of a water tank of height 20 m and has diameter of 10 m."
         },
         {
          "t": "p",
          "x": "Solution:"
         },
         {
          "t": "formula",
          "x": "Volume = r^2 h\n= 3.14 x 5^2 x 20\n= 3.14 x 25 x 20 = 1570 m^3"
         },
         {
          "t": "ol",
          "items": [
           "5.3: To measure the volume of an irregular solid object e.g. stone"
          ]
         },
         {
          "t": "img",
          "src": "images/foundation-science/to-measure-volume-of-stone.png",
          "alt": "Figure 3.3.4: To measure volume of stone"
         },
         {
          "t": "p",
          "x": "Figure 3.3.4: To measure volume of stone"
         }
        ]
       },
       {
        "h": "Method",
        "blocks": [
         {
          "t": "ol",
          "items": [
           "Half fill the measuring cylinder with water and record the volume(V1)",
           "Tie a piece of thread round a stone and lower it down into the water. Now read the new volume(V2)",
           "Subtract the first volume (V1) from the second volume (V2) to find the volume of the stone. Volume of stone = Final volume (V2) - Initial volume (V1)"
          ]
         },
         {
          "t": "p",
          "x": "The amount of water displaced is equal to the volume of the irregular object."
         }
        ]
       },
       {
        "h": "1.5.4: How to measure volume of liquid using a measuring cylinder",
        "blocks": [
         {
          "t": "p",
          "x": "Method:"
         }
        ]
       },
       {
        "h": "Method",
        "blocks": [
         {
          "t": "ol",
          "items": [
           "Place the measuring cylinder on a flat surface. This ensures accuracy.",
           "Pour a quantity of water into the measuring cylinder.",
           "Read the volume of water in the cylinder at the meniscus. The meniscus is curved downwards. Make sure your eye is leveled with the bottom of the curved surface of the meniscus.",
           "To have more practice with the students, fill different measuring cylinders with water and ask them to read the volumes. Record the different volumes and compare them"
          ]
         },
         {
          "t": "img",
          "src": "images/foundation-science/reading-volumes-of-water-liquid.png",
          "alt": "Figure 3.2.4: Reading volumes of water/liquid"
         },
         {
          "t": "p",
          "x": "Figure 3.2.4: Reading volumes of water/liquid"
         }
        ]
       }
