      "sections": [
       {
        "h": "Contact and Non-contact Forces",
        "blocks": [
         {
          "t": "ul",
          "items": [
           "BALANCED AND UNBALANCED FORCES"
          ]
         },
         {
          "t": "p",
          "x": "CONTACT FORCES: A contact force occurs when the object or material exerting a force touches the object or material on which the force acts. Examples of contact forces include: frictional force, magnetic force, impact force, tension force or spring force."
         },
         {
          "t": "p",
          "x": "NON-CONTACT FORCE: This is a force which acts on an object without coming physically in contact with it. The most familiar non-contact force is gravity. Other examples of noncontact forces are magnetic force, electrostatic force, and nuclear force."
         }
        ]
       }
      ]
