           "Nutrition: Amoeba feeds on microscopic organisms e.g. bacteria by engulfing them. The food particle becomes enclosed with a drop of water to form the food vacuole. Inside the food vacuole, enzymes are secreted to digest the food. Useful parts are absorbed and the residue is left behind as amoeba moves along. This is an example of holozoic nutrition.",
           "Excretion and osmo-regulation: The contractile vacuole acts as an organelle for elimination of metabolic wastes (excretion) and maintenance of water balance (osmo-regulation). The excess water together with nitrogenous wastes drain into the contractile vacuole which gradually expands and the contracts to squirt the water together with metabolic wastes.",
