          "t": "p",
          "x": "Like amoeba, paramecium feeds on microscopic organisms. Food particles are swept by the wave action of the cilia into mouth-like opening called the oral groove which leads into mouth pore (cytostome). A food vacuole is formed which moves round the cytoplasm. During this time, the food is digested and used. The undigested food is egested through the anal pore, found just behind the oral groove."
