          "x": "This is a pale-yellow fluid, composed mainly of 90% of water and forms about 55% of the volume of blood. It consists of proteins e.g. fibrinogen, soluble food substances e.g. glucose, amino acids, minerals e.g. sodium, calcium, metabolic wastes e.g. carbon dioxide; urea as well as hormones. The main function of plasma is to transport all these dissolved substances round the body."
