           "The heart is composed up of four chambers: two upper chambers called auricles and two lower chambers called ventricles. The ventricles have more muscular walls because the pump blood out of the heart where as the auricles have less muscular wall because they pump blood within the heart. The left ventricle is more muscular than the right ventricle because it pumps blood to the farthest point where as the right ventricle pumps blood to the lungs.",
           "There are valves in the heart that regulate the flow of blood between the four chambers and out of the heart so that blood flows in only one direction.",
