          "t": "p",
          "x": "i). Pulmonary (or Lung) circulation: This circuit takes deoxygenated blood from the heart to the lungs and takes oxygenated blood back to the heart. A brief outline of the flow of blood around the lungs is shown below: pulmonary artery LUNGS pulmonary vein left atrium"
